const body = ($json.body && $json.body) || $json;
const src = (body.source_video_url !== undefined && body.source_video_url !== null && String(body.source_video_url).trim() !== '')
  ? String(body.source_video_url).trim() : null;
if (src) {
  return [{ json: { ok: false, error: 'source_video_url не поддерживается — используй URL→видео сценарий' } }];
}
const script = (body.script !== undefined && body.script !== null && String(body.script).trim() !== '')
  ? String(body.script).trim() : '';
const topic = (body.topic !== undefined && body.topic !== null && String(body.topic).trim() !== '')
  ? String(body.topic).trim() : '';
let maxCount = (body.max_count !== undefined && body.max_count !== null && body.max_count !== '') ? Number(body.max_count) : 5;
if (!Number.isFinite(maxCount) || maxCount < 1) maxCount = 1;
maxCount = Math.min(10, Math.floor(maxCount));
const language = (body.language !== undefined && body.language !== null && String(body.language).trim() !== '')
  ? String(body.language).trim() : 'ru';
const aspectRatio = (body.aspect_ratio !== undefined && body.aspect_ratio !== null && String(body.aspect_ratio).trim() !== '')
  ? String(body.aspect_ratio).trim() : '9x16';
const style = (body.style !== undefined && body.style !== null && String(body.style).trim() !== '')
  ? String(body.style).trim() : 'Cinematic';
const webhookUrl = (body.webhook_url !== undefined && body.webhook_url !== null && String(body.webhook_url).trim() !== '')
  ? String(body.webhook_url).trim() : null;
if (script === '' && topic === '') {
  return [{ json: { ok: false, error: 'script или topic обязателен' } }];
}
return [{
  json: { ok: true, script: script, topic: topic, max_count: maxCount,
          language: language, aspect_ratio: aspectRatio, style: style, webhook_url: webhookUrl }
}];

const r = $json;
const balance = (r.remaining_credits !== undefined && r.remaining_credits !== null)
  ? Number(r.remaining_credits) : 0;
return [{ json: { ok: balance >= 30, balance: balance } }];

const v = $('Code validate').first().json;
let script = (v.script !== undefined && v.script !== null && String(v.script).trim() !== '')
  ? String(v.script).trim() : '';
try {
  const e = $('Exp Parse').first().json;
  if (e && e.ok === true && typeof e.script === 'string' && e.script.trim() !== '') {
    script = e.script.trim();
  }
} catch (err) { /* прямая ветка — Exp Parse не выполнялась */ }
const p = { script: script, aspect_ratio: v.aspect_ratio, style: v.style };
if (v.webhook_url) { p.webhook_url = v.webhook_url; }
return [{ json: { payload: p } }];

const r = $json;
const item = {
  id: r.id || null,
  status: r.status || null,
  video_output: r.video_output || null,
  preview: r.preview || null,
  editor_url: r.editor_url || null,
  progress: (r.progress !== undefined && r.progress !== null) ? r.progress : null,
  credits_used: r.credits_used || 0,
  duration: r.duration || null,
  failed_reason: r.failed_reason || null,
  created_at: r.created_at || null,
  updated_at: r.updated_at || null
};
return [{
  json: { ok: true, shorts_id: r.id || null, status: r.status || null,
          video_output: r.video_output || null, items: [item], raw: r }
}];

const v = $('Code validate').first().json;
const topic = (v.topic !== undefined && v.topic !== null) ? String(v.topic).trim() : '';
const prompt = 'Разверни тему «' + topic + '» в полный сценарий вертикального шортса (9:16) на 30–60 секунд чтения (200–400 слов), экспертный тон. Структура: хук (2 строки), основная часть, вывод с призывом к действию. Верни ТОЛЬКО текст сценария без пояснений, обернув его в теги <SCRIPT> и </SCRIPT>.';
return [{ json: { prompt: prompt } }];

const r = $json;
const answer = (r && r.answer !== undefined && r.answer !== null) ? String(r.answer) : '';
let script = '';
const marker = answer.match(/<SCRIPT>([\s\S]*?)<\/SCRIPT>/i);
if (marker && marker[1].trim() !== '') {
  script = marker[1].trim();
}
if (script === '') {
  const open = answer.indexOf('{');
  if (open !== -1) {
    let depth = 0;
    let end = -1;
    for (let i = open; i < answer.length; i++) {
      if (answer[i] === '{') { depth++; }
      else if (answer[i] === '}') { depth--; if (depth === 0) { end = i; break; } }
    }
    if (end !== -1) {
      try {
        const parsed = JSON.parse(answer.slice(open, end + 1));
        const cand = (parsed && typeof parsed === 'object')
          ? (parsed.script || parsed.text || parsed.content || parsed.answer) : null;
        if (cand !== null && cand !== undefined && String(cand).trim() !== '') {
          script = String(cand).trim();
        }
      } catch (e) { /* не JSON — пропускаем */ }
    }
  }
}
if (script === '') { script = answer.trim(); }
if (script === '') {
  return [{ json: { ok: false, error: 'не удалось сгенерировать сценарий' } }];
}
return [{ json: { ok: true, script: script } }];
